data.query:
query ($assetNumber: String!, $assetGroupId: String!){
  asset(
    where:{
      number:{ _eq: $assetNumber }
      status:{
        active:{ _eq: true}
      }
    }
  ) {
    edges {
      node {
        id
        number
        assetDesignId    
      }
    }
  }

	assetGroup(
    where:{
      id:{ _eq: $assetGroupId}
    }
  ) {
	  edges {
	    node {
	      id
        assetGroupDesign{
          assetGroupDesignAssetDesigns(
            where:{
              active:{ _eq: true}
            }
          ){
            edges{
              node{
                quantity
                assetDesignId
              }
            }
          }
        }
        assets {
          edges {
            node {
              assetDesignId
              _aggregate{
                number{
                  count
                }
              }

            }
          }
        }
	    }
	  }
	}
}

